// WF-6 must never fail: a failure here loses the very failure it reports. Everything is inside try/catch with a fixed fallback text.
// Never forward error.stack (server paths). Dedupe: at most one alert per workflow name per WINDOW_MS; the count suppressed since is added to the next alert that goes out.
const WINDOW_MS = 600000;
// The alert carries the provider's own error text: n8n's generic message ("Bad request - please check your parameters") plus the node error's
// description ("Your credit balance is too low ..."), when there is one and it adds something. A JSON-string description gives its human message
// (error.message), never the JSON. The cause is one line, at most 300 characters, key-like strings redacted. Anything odd: the message alone.
const withCause = (msg, h) => {
  try {
    const d = h && h.description;
    if (typeof d !== 'string') return msg;
    let t = d.trim();
    if (/^(\d{3}\s*)?\{/.test(t)) {
      const o = JSON.parse(t.slice(t.indexOf('{')));
      const s = (v) => (typeof v === 'string' ? v : '');
      t = s(o && o.error && o.error.message) || s(o && o.error) || s(o && o.message);
    }
    t = t.replace(/\b(?:sk|pk|xox[abp]|xapp)-[A-Za-z0-9_-]{8,}|\bBearer\s+\S+|\b\d{6,}:[A-Za-z0-9_-]{25,}|(?:x-api-key|api[-_ ]?key|authorization)\s*[:=]\s*(?:bearer\s+|basic\s+)?\S+/gi, '[redacted]').replace(/\s+/g, ' ').trim().slice(0, 300);
    if (!t || /^(null|undefined)$/i.test(t) || msg.toLowerCase().includes(t.toLowerCase())) return msg;
    return msg ? msg + ' — ' + t : t;
  } catch (x) { return msg; }
};
try {
  const e = $input.first().json || {};
  const ex = e.execution || {};
  const err = ex.error || (e.trigger || {}).error || {};
  const wf = (e.workflow && e.workflow.name) || 'workflow';
  const node = ex.lastNodeExecuted || (err.node && err.node.name) || '?';
  const msg = withCause(String(err.message || '').slice(0, 500), err);
  let suppressed = 0;
  try {
    const sd = $getWorkflowStaticData('global');
    sd.last = sd.last || {};
    sd.sup = sd.sup || {};
    const now = Date.now();
    if (sd.last[wf] && now - sd.last[wf] < WINDOW_MS) { sd.sup[wf] = (sd.sup[wf] || 0) + 1; return []; }
    suppressed = sd.sup[wf] || 0;
    sd.sup[wf] = 0;
    sd.last[wf] = now;
  } catch (x) { /* static data unavailable: send the alert rather than lose it */ }
  const lines = ['⚠️ ' + wf + ' failed at ' + node + ': ' + msg];
  if (suppressed) lines.push('(' + suppressed + ' more failure' + (suppressed === 1 ? '' : 's') + ' of ' + wf + ' suppressed since the last alert)');
  if (ex.url) lines.push('execution: ' + ex.url);
  return [{ json: { text: lines.join('\n') } }];
} catch (x) {
  return [{ json: { text: '⚠️ An n8n workflow failed and its alert could not be formatted - check the n8n executions list' } }];
}
